    {
        use std::os::unix::fs::PermissionsExt;
        if fs::metadata(path)?.permissions().mode() & 0o077 != 0 {
            return Err(InstallError::InvalidSettings {
                path: path.into(),
                reason: "composed Codex backup must be mode 0600".into(),
            });
        }
    }
    Ok(value)
}

