fn delegates_rtk(path: &Path, exe: &Path) -> bool {
    install::read_settings(path).map_or(true, |value| {
        value
            .get("hooks")
            .and_then(Value::as_object)
            .is_some_and(|hooks| has_delegate(hooks, exe))
